<template><div class="bars"><div v-for="item in data" :key="item.label" class="bar-row"><div class="bar-head"><span>{{item.label}}</span><strong>{{item.total}}</strong></div><div class="bar-track"><i :style="{width:`${Number(item.total||0)/max*100}%`}"/></div><small>站点 {{item.sites}} · 上游 {{item.sources}} · 任务 {{item.tasks}}</small></div><div v-if="!data.length" class="empty">暂无租户数据</div></div></template>
<script setup>import{computed}from"vue";const props=defineProps({data:{type:Array,default:()=>[]}}),max=computed(()=>Math.max(1,...props.data.map(item=>Number(item.total||0))));</script>
<style scoped>.bars{display:grid;gap:15px}.bar-row{display:grid;gap:5px}.bar-head{display:flex;justify-content:space-between;gap:12px;font-size:12px}.bar-head span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bar-track{height:8px;border-radius:6px;background:var(--fm-line-soft);overflow:hidden}.bar-track i{display:block;height:100%;min-width:3px;border-radius:6px;background:var(--fm-accent)}small,.empty{color:var(--fm-ink-muted);font-size:10px}</style>
